using AcxiomCRM.Data; using AcxiomCRM.Models; using AcxiomCRM.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;
[Authorize] public class LeadsController(ApplicationDbContext db,IAuditService audit):Controller {
 public async Task<IActionResult> Index(string? q,string? status){var x=db.Leads.AsQueryable();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager"))x=x.Where(a=>a.AssignedTo==User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value);if(!string.IsNullOrWhiteSpace(q))x=x.Where(a=>a.LeadName.Contains(q)||(a.CompanyName??"").Contains(q));if(!string.IsNullOrWhiteSpace(status))x=x.Where(a=>a.Status==status);ViewBag.Query=q;ViewBag.Status=status;return View(await x.OrderByDescending(a=>a.LeadId).ToListAsync());}
 public IActionResult Create()=>View(new Lead());
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(Lead m){if(!new[]{"New","Contacted","Qualified","Unqualified","Converted","Lost"}.Contains(m.Status))ModelState.AddModelError(nameof(m.Status),"Select a valid lead status.");if(!ModelState.IsValid)return View(m);m.LeadCode=string.IsNullOrWhiteSpace(m.LeadCode)?$"LED-{Guid.NewGuid().ToString("N")[..8].ToUpperInvariant()}":m.LeadCode;m.AssignedTo=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;db.Add(m);await db.SaveChangesAsync();await audit.WriteAsync("Create","Lead",m.LeadId.ToString(),null,m.LeadName);return RedirectToAction(nameof(Index));}
 public async Task<IActionResult> Edit(int id){var m=await db.Leads.FindAsync(id);if(m==null)return NotFound();if(!CanAccess(m.AssignedTo))return Forbid();return View(m);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(int id,Lead m){if(id!=m.LeadId)return BadRequest();var old=await db.Leads.AsNoTracking().FirstOrDefaultAsync(a=>a.LeadId==id);if(old==null)return NotFound();if(!CanAccess(old.AssignedTo))return Forbid();if(!new[]{"New","Contacted","Qualified","Unqualified","Converted","Lost"}.Contains(m.Status))ModelState.AddModelError(nameof(m.Status),"Select a valid lead status.");if(!ModelState.IsValid)return View(m);m.AssignedTo=old.AssignedTo;m.LeadCode=old.LeadCode;m.CreatedDate=old.CreatedDate;db.Update(m);await db.SaveChangesAsync();await audit.WriteAsync("Update","Lead",id.ToString(),old.Status,m.Status);return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Delete(int id){var m=await db.Leads.FindAsync(id);if(m==null)return NotFound();if(!CanAccess(m.AssignedTo))return Forbid();m.Status="Lost";await db.SaveChangesAsync();await audit.WriteAsync("MarkLost","Lead",id.ToString());return RedirectToAction(nameof(Index));}
 private bool CanAccess(string? owner)=>User.IsInRole("Admin")||User.IsInRole("Manager")||owner==User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;
}
